body:
Well, I finished with my brilliant idea. I tested it on Adreno 640 and confirmed that it is faster than master.

<details>
  <summary>Behold! 3 tap PCF5 and 7 tap PCF13</summary>

  ```
	float shadow;
	uint shadow_mode = light_array.data[light_base].flags & LIGHT_FLAGS_FILTER_MASK;
	shadow_uv.xyz /= shadow_uv.w;
	vec2 pp = floor(shadow_uv.xy / canvas_data.shadow_pixel_size) * canvas_data.shadow_pixel_size;
	float D = shadow_uv.z;
	float fx = fract(shadow_uv.x / canvas_data.shadow_pixel_size);

	if (shadow_mode == LIGHT_FLAGS_SHADOW_NEAREST) {
		vec2 tap0 = textureGather(sampler2D(shadow_atlas_texture, shadow_sampler), pp.xy).zw;
		shadow = mix(step(tap0.y, D), step(tap0.x, D), fx);
	} else if (shadow_mode == LIGHT_FLAGS_SHADOW_PCF5) {
		vec2 tap0 = textureGatherOffset(sampler2D(shadow_atlas_texture, shadow_sampler), pp.xy, ivec2(-2, 0)).zw;
		vec2 tap1 = textureGatherOffset(sampler2D(shadow_atlas_texture, shadow_sampler), pp.xy, ivec2(0, 0)).zw;
		vec2 tap2 = textureGatherOffset(sampler2D(shadow_atlas_texture, shadow_sampler), pp.xy, ivec2(2, 0)).zw;
		shadow = mix(step(tap0.y, D), step(tap0.x, D), fx);
		shadow += mix(step(tap0.x, D), step(tap1.y, D), fx);
		shadow += mix(step(tap1.y, D), step(tap1.x, D), fx);
		shadow += mix(step(tap1.x, D), step(tap2.y, D), fx);
		shadow += mix(step(tap2.y, D), step(tap2.x, D), fx);
		shadow /= 5.0;
	} else { //PCF13
		vec2 tap0 = textureGatherOffset(sampler2D(shadow_atlas_texture, shadow_sampler), pp.xy, ivec2(-6, 0)).zw;
		vec2 tap1 = textureGatherOffset(sampler2D(shadow_atlas_texture, shadow_sampler), pp.xy, ivec2(-4, 0)).zw;
		vec2 tap2 = textureGatherOffset(sampler2D(shadow_atlas_texture, shadow_sampler), pp.xy, ivec2(-2, 0)).zw;
		vec2 tap3 = textureGatherOffset(sampler2D(shadow_atlas_texture, shadow_sampler), pp.xy, ivec2(0, 0)).zw;
		vec2 tap4 = textureGatherOffset(sampler2D(shadow_atlas_texture, shadow_sampler), pp.xy, ivec2(2, 0)).zw;
		vec2 tap5 = textureGatherOffset(sampler2D(shadow_atlas_texture, shadow_sampler), pp.xy, ivec2(4, 0)).zw;
		vec2 tap6 = textureGatherOffset(sampler2D(shadow_atlas_texture, shadow_sampler), pp.xy, ivec2(6, 0)).zw;
		shadow = mix(step(tap0.y, D), step(tap0.x, D), fx);
		shadow += mix(step(tap0.x, D), step(tap1.y, D), fx);
		shadow += mix(step(tap1.y, D), step(tap1.x, D), fx);
		shadow += mix(step(tap1.x, D), step(tap2.y, D), fx);
		shadow += mix(step(tap2.y, D), step(tap2.x, D), fx);
		shadow += mix(step(tap2.x, D), step(tap3.y, D), fx);
		shadow += mix(step(tap3.y, D), step(tap3.x, D), fx);
		shadow += mix(step(tap3.x, D), step(tap4.y, D), fx);
		shadow += mix(step(tap4.y, D), step(tap4.x, D), fx);
		shadow += mix(step(tap4.x, D), step(tap5.y, D), fx);
		shadow += mix(step(tap5.y, D), step(tap5.x, D), fx);
		shadow += mix(step(tap5.x, D), step(tap6.y, D), fx);
		shadow += mix(step(tap6.y, D), step(tap6.x, D), fx);
		shadow /= 13.0;
	}
  ```
</details>

Turns out it doesn't work nicely with the "smoothness" setting. We would need to basically still do one tap per read and then manually interpolate. So this is going in the closet of forgotten ideas.
